<script setup lang="ts">
import { ref, onMounted, computed, onBeforeUnmount } from 'vue';
import { get, post } from '../../services/api';
import { useSession } from '../../stores/session';
import { useUi } from '../../stores/ui';
const session=useSession(),ui=useUi();
const config=ref<any>(null),loading=ref(true),saving=ref(false),error=ref(''),stats=ref<any>(null),compacting=ref(false),testing=ref(''),shown=ref<Record<string,boolean>>({});
const savedConfig=ref('');
const dirty=computed(()=>!!config.value && JSON.stringify(config.value)!==savedConfig.value);
async function leave(){if(saving.value||testing.value||compacting.value)return false;return !dirty.value||await ui.confirm({title:'放弃未保存的能力配置？',message:'MCP、Skill 或上下文配置尚未保存。',confirmText:'放弃修改',cancelText:'继续编辑',danger:true});}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue='';}}
const disabled=computed(()=>saving.value||session.busy||compacting.value||!!testing.value);
async function load(){loading.value=true;try{config.value=await get('/api/features');savedConfig.value=JSON.stringify(config.value);error.value='';}catch(e:any){error.value=e.message;}finally{loading.value=false;}}
onMounted(()=>{ui.dialogGuard=leave;window.addEventListener('beforeunload',beforeUnload);void load();});
onBeforeUnmount(()=>{if(ui.dialogGuard===leave)ui.dialogGuard=null;window.removeEventListener('beforeunload',beforeUnload);});
async function save(){saving.value=true;error.value='';try{config.value=await post('/api/features/save',{config:config.value});savedConfig.value=JSON.stringify(config.value);ui.toast('能力配置已保存，下次任务加载',{tone:'success'});return true;}catch(e:any){error.value=e.message;return false;}finally{saving.value=false;}}
function addSkill(){config.value.customSkills.push({id:'skill-'+crypto.randomUUID().slice(0,8),description:'我的个人技能',content:'',enabled:true});}
function addMcp(){config.value.mcpServers.push({id:'mcp-'+crypto.randomUUID().slice(0,8),name:'我的 MCP',url:'',token:'',enabled:false,useProxy:false,tools:[]});}
async function test(server:any){if(!await save())return;testing.value=server.id;try{config.value=await post('/api/features/mcp/test',{id:server.id});savedConfig.value=JSON.stringify(config.value);ui.toast('MCP 已连接并读取工具列表',{tone:'success'});}catch(e:any){error.value=e.message;}finally{testing.value='';}}
async function remove(kind:'mcpServers'|'customSkills',id:string){if(!await ui.confirm({title:'移除配置',message:'保存后将移除这项配置及其凭据。',confirmText:'移除',danger:true}))return;config.value[kind]=config.value[kind].filter((s:any)=>s.id!==id);}
async function context(){if(!session.currentChat)return;try{stats.value=await get('/api/context/stats?chat='+encodeURIComponent(session.currentChat.id));}catch(e:any){error.value=e.message;}}
async function compact(){if(!session.currentChat||!await ui.confirm({title:'压缩当前对话上下文',message:'将调用模型整理摘要，减少后续上下文用量。原始记录仍保存在服务端；压缩后暂不支持回退此对话。',confirmText:'开始压缩'}))return;compacting.value=true;error.value='';try{const result=await post('/api/context/compact',{thread:session.currentChat.id});await context();ui.toast(result.skipped?result.reason:'上下文已压缩',{tone:result.skipped?'info':'success'});}catch(e:any){error.value=e.message;}finally{compacting.value=false;}}
</script>
<template><div class="settings-pad capabilities-settings"><h3>内置能力与扩展</h3><p class="question-hint">上下文管理、问答、计划、记忆与后台任务由 Iris 原生提供。Skill 使用 Pi 的 Markdown 加载协议；MCP 通过经过校验的远程 HTTPS 连接，结果回到现有工具卡片和审批流程。配置修改需等待当前任务结束。</p><p v-if="loading" role="status">正在读取配置…</p><template v-else-if="config">
<h4>上下文管理</h4><label class="capability-check"><input v-model="config.autoCompaction" type="checkbox" :disabled="disabled" /> 接近上下文窗口上限时自动压缩（默认开启）</label><div class="background-actions"><button type="button" class="btn btn-quiet" :disabled="!session.currentChat||compacting" @click="context">查看当前上下文用量</button><button type="button" class="btn btn-quiet" :disabled="!session.currentChat||disabled" @click="compact">{{compacting?'压缩中…':'压缩当前对话'}}</button></div><p v-if="!session.currentChat" class="question-hint">打开已有对话后可查看用量和手动压缩。</p><p v-if="stats" class="question-hint">累计 {{stats.tokens?.total||0}} tokens · {{stats.totalMessages||0}} 条原始消息 · {{stats.toolCalls||0}} 次工具调用<span v-if="stats.contextUsage"> · 当前约 {{Math.round(stats.contextUsage.percent||0)}}%（{{stats.contextUsage.tokens}} / {{stats.contextUsage.contextWindow}}）</span></p>
<h4>内置 Skill</h4><label v-for="skill in config.builtinSkills" :key="skill.id" class="capability-skill"><input v-model="config.skills" :value="skill.id" type="checkbox" :disabled="disabled" /><span><strong>{{skill.name}}</strong><small>{{skill.description}}</small></span></label>
<h4>个人 Skill</h4><p class="question-hint">可粘贴自己的技能说明。仅加载 Markdown 文本，不执行其中的宿主脚本。每个技能最多 8000 字。</p><section v-for="skill in config.customSkills" :key="skill.id" class="capability-item"><label class="capability-check"><input v-model="skill.enabled" type="checkbox" :disabled="disabled" /> 启用 {{skill.id}}</label><label :for="'skill-desc-'+skill.id">技能说明</label><input :id="'skill-desc-'+skill.id" v-model="skill.description" maxlength="300" :disabled="disabled" /><label :for="'skill-body-'+skill.id">Markdown 内容</label><textarea :id="'skill-body-'+skill.id" v-model="skill.content" rows="6" maxlength="8000" style="resize: none" :disabled="disabled"></textarea><button type="button" class="btn btn-quiet" :disabled="disabled" @click="remove('customSkills',skill.id)">移除技能</button></section><button type="button" class="btn btn-quiet" :disabled="disabled||config.customSkills.length>=8" @click="addSkill">添加个人 Skill</button>
<h4>远程 MCP</h4><p class="question-hint">支持 Streamable HTTP 的 JSON / SSE 响应与 Bearer Token。先保存并测试，读取工具列表后启用。暂不执行宿主 stdio 程序或终端插件 UI；OAuth 服务需提供可用 Token。</p><section v-for="server in config.mcpServers" :key="server.id" class="capability-item"><label class="capability-check"><input v-model="server.enabled" type="checkbox" :disabled="disabled" /> 启用 {{server.name}}</label><label :for="'mcp-name-'+server.id">名称</label><input :id="'mcp-name-'+server.id" v-model="server.name" maxlength="60" :disabled="disabled" /><label :for="'mcp-url-'+server.id">公开 HTTPS MCP 端点</label><input :id="'mcp-url-'+server.id" v-model="server.url" type="url" placeholder="https://example.com/mcp" :disabled="disabled" /><label :for="'mcp-token-'+server.id">Bearer Token（{{server.hasToken?'已保存，留空保持':'可选'}}）</label><div class="search-key"><input :id="'mcp-token-'+server.id" v-model="server.token" :type="shown[server.id]?'text':'password'" autocomplete="new-password" :disabled="disabled" /><button type="button" class="btn btn-quiet" :aria-label="shown[server.id]?'隐藏 MCP Token':'显示 MCP Token'" @click="shown[server.id]=!shown[server.id]">{{shown[server.id]?'隐藏':'显示'}}</button></div><label class="capability-check"><input v-model="server.useProxy" type="checkbox" :disabled="disabled" /> 使用服务器代理</label><label v-if="server.hasToken" class="capability-check"><input v-model="server.clearToken" type="checkbox" :disabled="disabled" /> 清除已保存 Token</label><p class="question-hint">已发现 {{server.tools?.length||0}} 个工具：{{(server.tools||[]).map((t:any)=>t.name).join('、')||'尚未测试'}}</p><div class="background-actions"><button type="button" class="btn btn-quiet" :disabled="disabled" @click="test(server)">{{testing===server.id?'连接中…':'保存并测试'}}</button><button type="button" class="btn btn-quiet" :disabled="disabled" @click="remove('mcpServers',server.id)">移除服务</button></div></section><button type="button" class="btn btn-quiet" :disabled="disabled||config.mcpServers.length>=8" @click="addMcp">添加远程 MCP</button><div class="approval-actions"><button type="button" class="btn btn-solid" :disabled="disabled" @click="save">{{saving?'保存中…':'保存能力配置'}}</button></div>
</template><p v-if="error" class="status-error" role="alert">{{error}} <button v-if="!config" type="button" class="btn btn-quiet" @click="load">重试</button></p></div></template>
<style>
.capabilities-settings h4 { margin:24px 0 12px; }
.capability-check { display:flex;align-items:center;gap:8px;font-size:13px;margin:10px 0; }
.capability-skill { display:flex;align-items:flex-start;gap:10px;padding:12px 0;border-bottom:1px solid var(--line); }
.capability-skill input { margin-top:4px; }
.capability-skill strong { font-size:13px; }
.capability-skill small { display:block;color:var(--muted);font-size:12px; }
.capability-item { border:1px solid var(--line-strong);border-radius:var(--radius-sm);padding:12px;margin:12px 0; }
.capability-item>label:not(.capability-check) { display:block;margin:10px 0 4px;font-size:12px; }
.capability-item input:not([type='checkbox']),.capability-item textarea { min-width:0;width:100%;padding:8px;border:1px solid var(--line-strong);border-radius:var(--radius-xs);background:var(--surface); }
</style>
